"""Offline, bounded-DOM charts with all points retained for paged inspection."""
import html,json,math,re

SERIES=(('heart_rate','Battito','BPM'),('spo2','SpO₂','%'),('temperature','Temperatura anello','°C'),('motion','Movimento','s/record'),('step_increments','Passi','passi/record'),('respiratory_rate','Respiro','resp/min'))

def render(analysis):
    series={key:[p for p in analysis.get(key,[]) if all(type(p.get(k)) in (int,float) and math.isfinite(p[k]) for k in ('t','v'))] for key,_,_ in SERIES}
    counts={key:len(points) for key,points in series.items()}
    payload={'series':series,'labels':SERIES,'start':analysis['window_start'],'end':max(analysis['window_start']+1,analysis['window_end']),'stats':analysis['stats'],'cardio':analysis.get('cardio'),'provenance':analysis.get('cardio_provenance')}
    data=json.dumps(payload,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    title=html.escape(analysis.get('activity_name') or 'Allenamento')
    template='''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>__TITLE__</title><style>body{font:16px system-ui;background:#101c20;color:#e8f5f0;max-width:1100px;margin:auto;padding:24px}section{background:#1a2c30;padding:20px;margin:20px 0;border-radius:18px}canvas{width:100%;height:230px}table{border-collapse:collapse;font-size:13px;width:100%}td,th{padding:8px;border-bottom:1px solid #49605c}pre{white-space:pre-wrap}.scroll{overflow:auto;max-height:600px}button,select{padding:10px;margin:8px;background:#233e42;color:white;border:1px solid #6b9690;border-radius:8px}</style><h1>__TITLE__</h1><p>Istanti di acquisizione; passa sui grafici per i valori puntuali. Nessuna linea attraversa vuoti oltre 8 secondi. I punti interpolati non sono nuove misure indipendenti. I risultati provvisori possono cambiare.</p><main id="charts"></main><details><summary>Statistiche e fasce cardio</summary><pre id="stats"></pre></details><section><h2>Punti intermedi</h2><select id="metric" aria-label="Metrica dei campioni"></select><button id="prev">Precedenti</button><button id="next">Successivi</button><span id="page"></span><div class="scroll"><table><thead><tr><th>Secondi da inizio</th><th>Ora · Roma</th><th>Valore</th><th>Unità</th><th>Sorgente</th><th>Qualità</th><th>Interpolato</th><th>Provvisorio</th></tr></thead><tbody id="rows"></tbody></table></div></section><script type="application/json" id="data">__DATA__</script><script>
const d=JSON.parse(document.getElementById('data').textContent),clock=t=>new Date(t*1000).toLocaleString('it-IT',{timeZone:'Europe/Rome'}),sel=document.getElementById('metric');let page=0;
function node(tag,text,parent){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(parent)parent.appendChild(n);return n}
for(const [key,label,unit] of d.labels){const a=d.series[key],section=node('section',undefined,document.getElementById('charts'));node('h2',label+' · '+unit+' · '+a.length+' punti',section);const option=node('option',label,sel);option.value=key;if(!a.length){node('p','Nessun campione disponibile',section);continue}const c=node('canvas',undefined,section),info=node('p','Passa sul grafico per il dettaglio',section);c.width=1100;c.height=230;c.setAttribute('aria-label',label);const ctx=c.getContext('2d');let low=Infinity,high=-Infinity;for(const p of a){low=Math.min(low,p.v);high=Math.max(high,p.v)}const spread=Math.max(key==='heart_rate'?20:1,high-low);low-=spread*.1;high+=spread*.1;const x=t=>55+(t-d.start)/(d.end-d.start)*1015,y=v=>195-(v-low)/(high-low)*170;ctx.strokeStyle='#42615d';ctx.fillStyle='#d4e9e2';ctx.font='14px system-ui';for(let i=0;i<3;i++){const v=low+(high-low)*i/2;ctx.fillText(v.toFixed(1),0,y(v));ctx.beginPath();ctx.moveTo(55,y(v));ctx.lineTo(1070,y(v));ctx.stroke()}ctx.fillText(clock(d.start),55,224);ctx.fillText(clock(d.end),820,224);ctx.strokeStyle='#8fe0c5';ctx.fillStyle='#8fe0c5';ctx.lineWidth=2;ctx.beginPath();let previous=null;for(const p of a){if(key==='heart_rate'){if(!previous||p.t-previous.t>8)ctx.moveTo(x(p.t),y(p.v));else ctx.lineTo(x(p.t),y(p.v))}else{ctx.moveTo(x(p.t)+2,y(p.v));ctx.arc(x(p.t),y(p.v),2,0,Math.PI*2)}previous=p}ctx.stroke();c.onpointermove=e=>{const t=d.start+((e.clientX-c.getBoundingClientRect().left)/c.getBoundingClientRect().width*1100-55)/1015*(d.end-d.start);let l=0,r=a.length-1;while(l<r){const m=(l+r)>>1;if(a[m].t<t)l=m+1;else r=m}if(l&&Math.abs(a[l-1].t-t)<Math.abs(a[l].t-t))l--;const p=a[l];info.textContent=clock(p.t)+' · '+p.v+' '+unit+' · '+(p.source||'storico')+' · qualità '+(p.signal_quality??'non specificata')+(p.interpolated?' · interpolato':'')+(p.provisional?' · provvisorio':'')}}
document.getElementById('stats').textContent=JSON.stringify({statistiche:d.stats,fasce:d.cardio,provenienza:d.provenance},null,2);
function table(){const a=d.series[sel.value]||[],unit=d.labels.find(x=>x[0]===sel.value)?.[2]||'',body=document.getElementById('rows');page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(a.length/100)-1)));body.replaceChildren();for(const p of a.slice(page*100,page*100+100)){const tr=node('tr',undefined,body);for(const v of [(p.t-d.start).toFixed(1),clock(p.t),p.v,unit,p.source||'storico',p.signal_quality??'',!!p.interpolated,!!p.provisional])node('td',String(v),tr)}document.getElementById('page').textContent=(a.length?page*100+1:0)+'–'+Math.min(a.length,(page+1)*100)+' di '+a.length;document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=(page+1)*100>=a.length}sel.onchange=()=>{page=0;table()};document.getElementById('prev').onclick=()=>{page--;table()};document.getElementById('next').onclick=()=>{page++;table()};table();
</script></html>'''
    return re.sub('__TITLE__|__DATA__',lambda m:title if m.group()=='__TITLE__' else data,template),counts
